	pr_err("Could not read %u bytes while handling misaligned cmd\n",
	       nbytes);

	for_each_sgtable_sg(sg_table, sg, i) {
		page = sg_page(sg);
		if (page)
			__free_page(page);
	}
	kfree(cmd->read_iov);
